package com.github.khendricksen.extendedbanksearch;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.EquipmentInventorySlot;

/**
 * Maps user-typed slot words to real OSRS equipment slots.
 *
 * <p>Only the 11 true gear slots are mapped. {@link EquipmentInventorySlot} also defines
 * player-appearance "kit" slots (ARMS, HAIR, JAW) which are not equippable gear and are never mapped
 * here.
 *
 * <p>Kept to true slot synonyms only. Item subtype words (e.g. "platebody", "ward", "mask") are
 * narrower than a slot, so they are deliberately absent here and fall through to the native
 * item-name search.
 */
final class EquipmentSlots
{
	private static final Map<String, EquipmentInventorySlot> ALIASES = build();

	private static Map<String, EquipmentInventorySlot> build()
	{
		Map<String, EquipmentInventorySlot> m = new HashMap<>();
		put(m, EquipmentInventorySlot.HEAD, "head", "helm", "helmet", "hat", "hood");
		put(m, EquipmentInventorySlot.CAPE, "cape", "cloak", "back");
		put(m, EquipmentInventorySlot.AMULET, "amulet", "ammy", "neck", "necklace");
		put(m, EquipmentInventorySlot.AMMO, "ammo", "ammunition", "arrow", "arrows", "bolt", "bolts", "quiver");
		put(m, EquipmentInventorySlot.WEAPON, "weapon", "wep", "weap", "mainhand", "main-hand", "main", "2h");
		put(m, EquipmentInventorySlot.BODY, "body", "chest", "top", "torso");
		put(m, EquipmentInventorySlot.SHIELD, "shield", "offhand", "off-hand", "off");
		put(m, EquipmentInventorySlot.LEGS, "legs", "leg", "bottom", "bottoms", "trousers");
		put(m, EquipmentInventorySlot.GLOVES, "hands", "hand", "gloves", "glove", "gauntlets", "vambraces");
		put(m, EquipmentInventorySlot.BOOTS, "feet", "foot", "boots", "boot", "shoes");
		put(m, EquipmentInventorySlot.RING, "ring");
		return Collections.unmodifiableMap(m);
	}

	private static void put(Map<String, EquipmentInventorySlot> m, EquipmentInventorySlot slot, String... aliases)
	{
		for (String alias : aliases)
		{
			m.put(alias, slot);
		}
	}

	/**
	 * Resolves a single lowercase word to its equipment slot, or {@code null} if it isn't a slot word.
	 */
	static EquipmentInventorySlot resolve(String word)
	{
		return ALIASES.get(word);
	}

	private EquipmentSlots()
	{
	}
}

package com.github.khendricksen.extendedbanksearch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(ExtendedBankSearchConfig.GROUP)
public interface ExtendedBankSearchConfig extends Config
{
	String GROUP = "extendedbanksearch";

	@ConfigItem(
		keyName = "debugLogging",
		name = "Debug logging",
		description = "Log each bank search query and tested item id to the client log. "
			+ "Useful while developing; leave off for normal play."
	)
	default boolean debugLogging()
	{
		return false;
	}
}

package com.github.khendricksen.extendedbanksearch;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Extends the native in-game bank search box with stat-, slot- and warmth-based queries.
 *
 * <p>The plugin does NOT build any UI of its own. RuneLite's bank filter fires a {@code bankSearchFilter}
 * script callback once per item while the search prompt is open; the plugin hooks that event (exactly the
 * way core {@code BankPlugin} does for its {@code ha > 5k} value search) and force-shows items that
 * match the query by writing {@code 1} into the script's return slot.
 *
 * <p>The return is <b>additive</b>: writing {@code 1} only force-includes an item, and the game
 * still runs its own item-name match independently. So pure stat/slot queries are owned entirely by
 * the plugin's logic (clean AND), but mixing a name with stats (e.g. {@code dragon prayer>6}) yields an OR,
 * not an AND. See README.
 */
@Slf4j
@PluginDescriptor(
	name = "Extended Bank Search",
	description = "Search your bank by equipment stats, slot and warmth, straight from the native search box",
	tags = {"bank", "search", "stat", "stats", "slot", "equipment", "gear", "armour", "armor", "warm", "wintertodt", "food"}
)
public class ExtendedBankSearchPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ExtendedBankSearchConfig config;

	@Override
	protected void startUp()
	{
		log.debug("Extended Bank Search started");
	}

	@Override
	protected void shutDown()
	{
		log.debug("Extended Bank Search stopped");
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!"bankSearchFilter".equals(event.getEventName()))
		{
			return;
		}

		final int[] intStack = client.getIntStack();
		final Object[] objectStack = client.getObjectStack();
		final int intStackSize = client.getIntStackSize();
		final int objectStackSize = client.getObjectStackSize();

		final int itemId = intStack[intStackSize - 1];
		final String search = (String) objectStack[objectStackSize - 1];

		if (config.debugLogging())
		{
			log.debug("bankSearchFilter: itemId={} search=\"{}\"", itemId, search);
		}

		if (matches(itemId, search))
		{
			// return true -> force-show this item (additive, ORs with the native name match)
			intStack[intStackSize - 2] = 1;
		}
		// else: leave the stack untouched -> falls through to native behaviour
	}

	/**
	 * Decide whether the query force-shows this item.
	 *
	 * <p>Parse the query; if it recognises nothing, do nothing and let the native name search handle
	 * it. Otherwise every recognised part must pass (AND):
	 * <ul>
	 *   <li>{@code warm} / {@code food} are item-property tests, evaluated independently of equipment
	 *       stats (edible items aren't equipable and warm items might not have any surfaceable stats);</li>
	 *   <li>slot / stat / range conditions require the item to be equipable with non-null equipment
	 *       stats.</li>
	 * </ul>
	 */
	private boolean matches(int itemId, String search)
	{
		ParsedQuery query = QueryParser.parse(search);
		if (query.isEmpty())
		{
			return false;
		}

		// Canonicalise once: bank items can be placeholders, and the plugin needs the base id for
		// every lookup below.
		final int canonicalId = itemManager.canonicalize(itemId);

		if (query.requiresWarm() && !WarmClothing.isWarm(canonicalId))
		{
			return false;
		}

		if (query.requiresFood() && !isFood(canonicalId))
		{
			return false;
		}

		if (!query.equipmentConditions().isEmpty())
		{
			ItemStats stats = itemManager.getItemStats(canonicalId);
			if (stats == null || !stats.isEquipable())
			{
				return false;
			}

			ItemEquipmentStats eq = stats.getEquipment();
			if (eq == null)
			{
				return false;
			}

			for (ItemCondition condition : query.equipmentConditions())
			{
				if (!condition.test(eq))
				{
					return false;
				}
			}
		}

		return true;
	}

	/**
	 * Whether the item is edible, i.e. exposes an {@code "Eat"} inventory action. This catches food without
	 * a hardcoded list; drinks (potions, beer) use {@code "Drink"} and are deliberately not included.
	 */
	private boolean isFood(int canonicalItemId)
	{
		ItemComposition comp = itemManager.getItemComposition(canonicalItemId);
		for (String action : comp.getInventoryActions())
		{
			if ("Eat".equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	@Provides
	ExtendedBankSearchConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ExtendedBankSearchConfig.class);
	}
}

package com.github.khendricksen.extendedbanksearch;

import net.runelite.client.game.ItemEquipmentStats;

/**
 * A single recognised condition from a parsed query (e.g. "is a head-slot item", or "prayer &gt; 6").
 *
 * <p>The caller guarantees the item is equipable and has non-null equipment stats before calling
 * {@link #test}, so implementations never need to null-check.
 */
@FunctionalInterface
interface ItemCondition
{
	boolean test(ItemEquipmentStats eq);
}

package com.github.khendricksen.extendedbanksearch;

/**
 * Comparison operators usable in a stat query, e.g. the {@code >} in {@code prayer>6}.
 *
 * <p>The two-character operators must be listed/matched before the single-character ones so that
 * {@code >=} is never mis-read as {@code >} followed by {@code =}. {@link #PATTERN} encodes that
 * ordering for the parser's tokeniser.
 */
enum Operator
{
	GE(">="),
	LE("<="),
	GT(">"),
	LT("<"),
	EQ("=");

	/** Alternation of every operator token, longest first — used to split operators out of the query. */
	static final String PATTERN = ">=|<=|>|<|=";

	private final String token;

	Operator(String token)
	{
		this.token = token;
	}

	/**
	 * Resolves a token to its operator, or {@code null} if it isn't one.
	 */
	static Operator fromToken(String token)
	{
		for (Operator op : values())
		{
			if (op.token.equals(token))
			{
				return op;
			}
		}
		return null;
	}

	boolean test(int actual, int threshold)
	{
		switch (this)
		{
			case GT:
				return actual > threshold;
			case LT:
				return actual < threshold;
			case GE:
				return actual >= threshold;
			case LE:
				return actual <= threshold;
			case EQ:
				return actual == threshold;
			default:
				return false;
		}
	}
}

package com.github.khendricksen.extendedbanksearch;

import java.util.List;

/**
 * The recognised parts of a bank-search query.
 *
 * <p>Equipment conditions (slot / stat / range) are tested against an item's {@link
 * net.runelite.client.game.ItemEquipmentStats}. The {@code warm} and {@code food} flags are separate
 * item-property tests that bypass the equipment-stats checks (edible items aren't equipable and
 * warm items don't always have stats). The caller requires all of them to match (AND).
 */
final class ParsedQuery
{
	private final List<ItemCondition> equipmentConditions;
	private final boolean warm;
	private final boolean food;

	ParsedQuery(List<ItemCondition> equipmentConditions, boolean warm, boolean food)
	{
		this.equipmentConditions = equipmentConditions;
		this.warm = warm;
		this.food = food;
	}

	List<ItemCondition> equipmentConditions()
	{
		return equipmentConditions;
	}

	boolean requiresWarm()
	{
		return warm;
	}

	boolean requiresFood()
	{
		return food;
	}

	/** True when nothing was recognised, so the caller should let the native name search handle it. */
	boolean isEmpty()
	{
		return equipmentConditions.isEmpty() && !warm && !food;
	}
}

package com.github.khendricksen.extendedbanksearch;

import java.util.ArrayList;
import java.util.List;
import java.util.function.ToIntFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Parses bank-search query strings; see {@link #parse}.
 */
final class QueryParser
{
	/** A range value like {@code 2-6}: two integers joined by a single hyphen. */
	private static final Pattern RANGE = Pattern.compile("(-?\\d+)-(-?\\d+)");

	/**
	 * Parses a bank-search query string into a {@link ParsedQuery} — the conditions an item must satisfy.
	 *
	 * <p>An {@link ParsedQuery#isEmpty() empty} result means "nothing recognised", so the caller leaves
	 * the item untouched and the native item-name search handles it. Otherwise every recognised condition
	 * must be satisfied (AND) for an item to force-show.
	 *
	 * <p>Recognised:
	 * <ul>
	 *   <li>slot words — {@code helm}, {@code legs}, … (single token)</li>
	 *   <li>stat comparisons — {@code prayer>6}, {@code dstab >= 50}, {@code magic attack>20}
	 *       (stat key, possibly two words, then an operator, then an integer)</li>
	 *   <li>stat ranges — {@code prayer 2-6} (stat key then an inclusive low-high range)</li>
	 *   <li>bare stat words — {@code prayer}, {@code melee str} (a stat key with nothing comparable
	 *       after it is treated as an implicit {@code > 0})</li>
	 *   <li>warm clothing — {@code warm} / {@code warmth} / {@code wintertodt} (an item-id membership
	 *       test handled separately from the equipment conditions, see {@link WarmClothing})</li>
	 *   <li>food — {@code food} / {@code edible} / {@code eat} (matches items with an "Eat" inventory
	 *       action; also handled separately from the equipment conditions)</li>
	 * </ul>
	 *
	 * <p>Stat keys use longest-match so multi-word forms beat bare ones (see {@link StatAliases}).
	 * Unrecognised tokens are ignored — they still widen the results additively through the native name
	 * match (see README).
	 */
	static ParsedQuery parse(String query)
	{
		List<ItemCondition> conditions = new ArrayList<>();
		boolean warm = false;
		boolean food = false;
		if (query == null)
		{
			return new ParsedQuery(conditions, false, false);
		}

		// Split operators out as their own tokens so "prayer>6" and "prayer > 6" tokenise the same.
		String normalized = query.trim().toLowerCase().replaceAll("(" + Operator.PATTERN + ")", " $1 ");
		String[] tokens = normalized.split("\\s+");

		int i = 0;
		while (i < tokens.length)
		{
			if (tokens[i].isEmpty())
			{
				i++;
				continue;
			}

			if (isWarmWord(tokens[i]))
			{
				warm = true;
				i++;
				continue;
			}

			if (isFoodWord(tokens[i]))
			{
				food = true;
				i++;
				continue;
			}

			int consumed = tryStatComparison(tokens, i, conditions);
			if (consumed > 0)
			{
				i += consumed;
				continue;
			}

			EquipmentInventorySlot slot = EquipmentSlots.resolve(tokens[i]);
			if (slot != null)
			{
				conditions.add(new SlotCondition(slot));
				i++;
				continue;
			}

			// Unrecognised token -> ignore it.
			i++;
		}

		return new ParsedQuery(conditions, warm, food);
	}

	private static boolean isWarmWord(String token)
	{
		return "warm".equals(token) || "warmth".equals(token) || "wintertodt".equals(token);
	}

	private static boolean isFoodWord(String token)
	{
		return "food".equals(token) || "edible".equals(token) || "eat".equals(token);
	}

	/**
	 * Tries range, then operator+integer, then falls back to >0, once a stat key resolves.
	 * Returns the tokens consumed, or 0 if no key resolves.
	 */
	private static int tryStatComparison(String[] tokens, int start, List<ItemCondition> out)
	{
		int maxWords = Math.min(StatAliases.MAX_WORDS, tokens.length - start);
		for (int words = maxWords; words >= 1; words--)
		{
			ToIntFunction<ItemEquipmentStats> getter = StatAliases.resolve(join(tokens, start, words));
			if (getter == null)
			{
				continue;
			}

			// The longest key wins; once it resolves we never fall back to a shorter key. This is safe
			// because a multi-word key's trailing word (e.g. "def" in "stab def", "strength" in "melee
			// strength") is never an operator or number.
			int next = start + words;
			if (next < tokens.length)
			{
				// Range form: a single "low-high" token.
				int[] range = parseRange(tokens[next]);
				if (range != null)
				{
					out.add(new RangeCondition(getter, range[0], range[1]));
					return words + 1;
				}

				// Operator form: operator token then integer.
				Operator operator = Operator.fromToken(tokens[next]);
				int valueIndex = next + 1;
				if (operator != null && valueIndex < tokens.length)
				{
					Integer threshold = parseInt(tokens[valueIndex]);
					if (threshold != null)
					{
						out.add(new StatCondition(getter, operator, threshold));
						return words + 2;
					}
				}
			}

			out.add(new StatCondition(getter, Operator.GT, 0));
			return words;
		}

		return 0;
	}

	private static int[] parseRange(String token)
	{
		Matcher m = RANGE.matcher(token);
		if (!m.matches())
		{
			return null;
		}
		// parseInt over Integer.parseInt, returns null instead of throwing when a
		// bound doesn't fit in an int, so an oversized range is simply not recognised as a range
		Integer low = parseInt(m.group(1));
		Integer high = parseInt(m.group(2));
		if (low == null || high == null)
		{
			return null;
		}
		return new int[]{low, high};
	}

	private static String join(String[] tokens, int start, int count)
	{
		if (count == 1)
		{
			return tokens[start];
		}

		StringBuilder sb = new StringBuilder(tokens[start]);
		for (int i = 1; i < count; i++)
		{
			sb.append(' ').append(tokens[start + i]);
		}
		return sb.toString();
	}

	private static Integer parseInt(String token)
	{
		if (!token.matches("-?\\d+"))
		{
			return null;
		}
		try
		{
			return Integer.parseInt(token);
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private QueryParser()
	{
	}
}

package com.github.khendricksen.extendedbanksearch;

import java.util.function.ToIntFunction;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Matches items whose equipment bonus falls within an inclusive range, e.g. {@code prayer 2-6}.
 * The bounds are normalised so {@code 6-2} behaves the same as {@code 2-6}.
 */
final class RangeCondition implements ItemCondition
{
	private final ToIntFunction<ItemEquipmentStats> getter;
	private final int low;
	private final int high;

	RangeCondition(ToIntFunction<ItemEquipmentStats> getter, int a, int b)
	{
		this.getter = getter;
		this.low = Math.min(a, b);
		this.high = Math.max(a, b);
	}

	@Override
	public boolean test(ItemEquipmentStats eq)
	{
		int value = getter.applyAsInt(eq);
		return value >= low && value <= high;
	}
}

package com.github.khendricksen.extendedbanksearch;

import net.runelite.api.EquipmentInventorySlot;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Matches items that occupy a given equipment slot, e.g. {@code helm} -&gt; everything in the head
 * slot. Compares the item's slot index against the enum's {@link EquipmentInventorySlot#getSlotIdx()}
 * (never a hardcoded number, since slot indices are not contiguous).
 */
final class SlotCondition implements ItemCondition
{
	private final EquipmentInventorySlot slot;

	SlotCondition(EquipmentInventorySlot slot)
	{
		this.slot = slot;
	}

	@Override
	public boolean test(ItemEquipmentStats eq)
	{
		return eq.getSlot() == slot.getSlotIdx();
	}
}

package com.github.khendricksen.extendedbanksearch;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.ToIntFunction;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Maps user-typed stat words to the equipment-bonus getter they query.
 *
 * <p>Aliases may be one or two words ({@link #MAX_WORDS}); the parser tries the longest match first,
 * so multi-word forms win over bare ones. That ordering is what disambiguates the genuinely
 * ambiguous words:
 *
 * <ul>
 *   <li>{@code magic attack} &rarr; attack-magic, {@code magic def} &rarr; defence-magic,
 *       {@code magic damage} &rarr; magic-damage%, but bare {@code magic} defaults to
 *       <b>attack</b>-magic. {@code mage} is a synonym of {@code magic} everywhere.</li>
 *   <li>{@code ranged strength} &rarr; ranged strength, {@code ranged attack} &rarr; attack-ranged,
 *       {@code ranged def} &rarr; defence-ranged, but bare {@code range}/{@code ranged} defaults to
 *       <b>attack</b>-ranged ({@code range} and {@code ranged} are interchangeable).</li>
 *   <li>Bare {@code slash}/{@code crush}/{@code stab} default to the attack bonus (how players talk).</li>
 * </ul>
 *
 * <p>Defaulting bare magic/range to attack is the riskier of these choices — unlike stab/slash/crush,
 * which only ever mean the attack bonus colloquially, magic and range genuinely have other things a player
 * might mean (defence, damage, strength).
 */
final class StatAliases
{
	/** Largest number of words in any alias; the parser joins at most this many tokens when matching. */
	static final int MAX_WORDS = 2;

	private static final Map<String, ToIntFunction<ItemEquipmentStats>> ALIASES = build();

	private static Map<String, ToIntFunction<ItemEquipmentStats>> build()
	{
		Map<String, ToIntFunction<ItemEquipmentStats>> m = new HashMap<>();

		put(m, ItemEquipmentStats::getPrayer, "prayer", "pray");
		put(m, ItemEquipmentStats::getStr, "str", "strength", "melee str", "melee strength");
		put(m, ItemEquipmentStats::getRstr,
			"rstr", "ranged str", "ranged strength", "range str", "range strength");
		// Magic damage is stored as a float percentage; truncate to int for comparison.
		put(m, eq -> (int) eq.getMdmg(), "mdmg", "magic damage", "magic dmg", "mage damage", "mage dmg");

		// Attack bonuses. Both word orders accepted.
		put(m, ItemEquipmentStats::getAstab, "astab", "stab", "stab attack", "attack stab");
		put(m, ItemEquipmentStats::getAslash, "aslash", "slash", "slash attack", "attack slash");
		put(m, ItemEquipmentStats::getAcrush, "acrush", "crush", "crush attack", "attack crush");
		put(m, ItemEquipmentStats::getAmagic,
			"amagic", "magic", "mage", "magic attack", "attack magic", "mage attack", "attack mage");
		put(m, ItemEquipmentStats::getArange,
			"arange", "range", "ranged", "ranged attack", "range attack", "attack ranged", "attack range");

		// Defence bonuses. Both word orders accepted (e.g. "magic def" and "def magic").
		put(m, ItemEquipmentStats::getDstab, "dstab", "def stab", "defence stab", "stab def", "stab defence");
		put(m, ItemEquipmentStats::getDslash,
			"dslash", "def slash", "defence slash", "slash def", "slash defence");
		put(m, ItemEquipmentStats::getDcrush,
			"dcrush", "def crush", "defence crush", "crush def", "crush defence");
		put(m, ItemEquipmentStats::getDmagic,
			"dmagic", "magic def", "magic defence", "def magic", "defence magic",
			"mage def", "mage defence", "def mage", "defence mage");
		put(m, ItemEquipmentStats::getDrange,
			"drange", "ranged def", "ranged defence", "range def", "range defence",
			"def ranged", "defence ranged", "def range", "defence range");

		put(m, ItemEquipmentStats::getAspeed, "speed", "aspeed");

		return Collections.unmodifiableMap(m);
	}

	private static void put(Map<String, ToIntFunction<ItemEquipmentStats>> m,
		ToIntFunction<ItemEquipmentStats> getter, String... aliases)
	{
		for (String alias : aliases)
		{
			m.put(alias, getter);
		}
	}

	/**
	 * Resolves a (possibly multi-word, space-joined) lowercase key to its bonus getter, or
	 * {@code null} if it isn't a known stat.
	 */
	static ToIntFunction<ItemEquipmentStats> resolve(String key)
	{
		return ALIASES.get(key);
	}

	private StatAliases()
	{
	}
}

package com.github.khendricksen.extendedbanksearch;

import java.util.function.ToIntFunction;
import net.runelite.client.game.ItemEquipmentStats;

/**
 * Matches items whose equipment bonus satisfies a comparison, e.g. {@code prayer>6} or
 * {@code dstab>=50}. The getter pulls the relevant bonus off the item's stats; the operator compares
 * it against the typed threshold.
 */
final class StatCondition implements ItemCondition
{
	private final ToIntFunction<ItemEquipmentStats> getter;
	private final Operator operator;
	private final int threshold;

	StatCondition(ToIntFunction<ItemEquipmentStats> getter, Operator operator, int threshold)
	{
		this.getter = getter;
		this.operator = operator;
		this.threshold = threshold;
	}

	@Override
	public boolean test(ItemEquipmentStats eq)
	{
		return operator.test(getter.applyAsInt(eq), threshold);
	}
}

